update app.parameter_set_search_profiles p set topic_terms=(select jsonb_agg(term order by term) from (select distinct jsonb_array_elements_text(p.topic_terms || '["авангард", "avant-garde", "avantgarde", "футур", "futuris", "супремат", "suprematis", "рационал", "rationalis", "экспрессиони", "expressionis", "неокласси", "neoclassic", "ампир", "empire", "метаболи", "metabolis", "регионал", "regionalis", "минимал", "minimalis", "деконструктив", "deconstructiv", "органич", "органик", "organic", "символи", "symbolis", "неомодерн", "neomodern", "contemporary"]'::jsonb) term) t) from app.parameter_sets s where s.id=p.set_id and s.code='style_solutions';
update app.parameter_set_research_tasks t set model_name='google/gemini-2.5-pro', instruction=t.instruction || E'\nКаталог содержит лишь часть понятий. Для каждой подтверждённой источником эпохи, школы, течения, авторского направления или морфологического признака ищи точное соответствие по смыслу и оси. Если его нет, обязательно верни concept_id=null и точное название в candidate_name. Запрещено подменять понятие близким из каталога. Сохраняй весь спектр оценок. classification_negation допустимо исключительно когда автор прямо отрицает принадлежность объекта к конкретному понятию или явно отвергает его. Молчание, отсутствие упоминания и описание другого признака не являются отрицанием.' from app.parameter_sets s where s.id=t.set_id and s.code='style_solutions';
